PREFIX g: <https://d-nb.info/standards/elementset/gnd#>
PREFIX gender: <https://d-nb.info/standards/vocab/gnd/gender#>
PREFIX area: <https://d-nb.info/standards/vocab/gnd/geographic-area-code#>
SELECT ?name (COUNT(DISTINCT ?person) AS ?count) WHERE {
 ?person a g:DifferentiatedPerson ; g:geographicAreaCode area:XA-GB ; g:gender ?sex ; g:preferredNameEntityForThePerson ?n .
 ?n g:surname ?surname . OPTIONAL { ?n g:prefix ?prefix . }
 BIND(IF(BOUND(?prefix), CONCAT(?prefix, " ", ?surname), ?surname) AS ?name)
 FILTER NOT EXISTS { ?person g:geographicAreaCode ?otherCountry . FILTER(?otherCountry != area:XA-GB) }
 FILTER NOT EXISTS { ?person g:gender ?otherSex . FILTER(?otherSex != ?sex) }
 FILTER NOT EXISTS { ?person a ?excluded . VALUES ?excluded { g:Pseudonym g:CollectivePseudonym g:LiteraryOrLegendaryCharacter g:Gods g:Spirits g:RoyalOrMemberOfARoyalHouse } }
 FILTER NOT EXISTS { ?person g:realIdentity ?real . }
 FILTER NOT EXISTS { ?real g:pseudonym ?person . }
 FILTER NOT EXISTS { ?person g:realNameOfThePerson ?realName . }
 FILTER NOT EXISTS { ?person g:variantNameEntityForThePerson ?variant . ?variant a g:RealNameOfThePerson . }
} GROUP BY ?name HAVING (COUNT(DISTINCT ?person) >= 5) ORDER BY DESC(?count) ?name
